use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn is_reverse_of(a: Seq<f32>, b: Seq<f32>) -> bool {
    a.len() == b.len() &&
    forall|i: int| 0 <= i < a.len() ==> a[i] == b[a.len() - 1 - i]
}

fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result@.len() == m@.len(),
        is_reverse_of(result@, m@),
{
    let n = m.len();
    let mut result_vec: Vec<f32> = Vec::new();
    let mut i: usize = 0;
    
    while i < n
        invariant
            0 <= i <= n,
            result_vec@.len() == i,
            forall|j: int| 0 <= j < i ==> result_vec@[j] == m@[n - 1 - j],
        decreases n - i,
    {
        let idx = n - 1 - i;
        assert(0 <= idx < n) by {
            // Prove idx is within bounds
            assert(i < n);
            assert(n - 1 - i >= 0);
        }
        
        let elem = *m.index(idx);
        result_vec.push(elem);
        
        i = i + 1;
    }
    
    result_vec
}

}
